files.content:
.card { min-width: 0; border: 1px solid var(--border); border-radius: var(--radius-surface); padding: var(--space-6); background: var(--surface); box-shadow: var(--shadow-resting); }
.top { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); margin-bottom: var(--space-8); }
.label { color: var(--text-secondary); font-size: var(--text-sm); font-weight: 500; }
.changeBadge { border: 1px solid var(--border); border-radius: var(--radius-pill); padding: 3px 8px; color: var(--text-secondary); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.valueRow { margin-top: var(--space-2); }
.context { margin: var(--space-4) 0 0; color: var(--text-muted); font-size: var(--text-sm); line-height: var(--leading-body); }

@media (max-width: 380px) { .card { padding: var(--space-4); } .top { align-items: flex-start; flex-wrap: wrap; margin-bottom: var(--space-6); } }
.changeBadge[data-trend] { border-color: transparent; transition: color var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard); }
.changeBadge[data-trend="up"] { background: color-mix(in oklch, var(--success) 11%, transparent); color: var(--success); }
.changeBadge[data-trend="down"] { background: color-mix(in oklch, var(--danger) 11%, transparent); color: var(--danger); }
